import std.io

pub type AppError = Failed(String)

fn square(n: Int64) -> Int64 {
    return n * n
}

fn apply(f: fn(Int64) -> Int64, v: Int64) -> Int64 {
    return f(v)
}

pub fn main() effect io -> Result<(), AppError> {
    let f = square
    let a = apply(f, 2)
    let b = apply(square, 3)
    let c = apply(|x| x * 2, 5)
    io.println("${a}")
    io.println("${b}")
    io.println("${c}")
    return Ok(())
}
